WindowsIntegrationDialog::WindowsIntegrationDialog(FolderRegistry registry,QString executable,QString extension,QWidget *parent):QDialog(parent),m_registry(std::move(registry)),m_executable(std::move(executable)){
    setObjectName("windowsIntegrationDialog");setWindowTitle(tr("Associações e abertura de pastas"));resize(950,700);auto *layout=new QVBoxLayout(this);auto *tabs=new QTabWidget(this);tabs->setObjectName("windowsIntegrationTabs");layout->addWidget(tabs,1);
    auto *files=new QWidget(tabs);auto *fileLayout=new QVBoxLayout(files);tabs->addTab(files,tr("Tipos de arquivo"));plain(tr("Consulte o aplicativo registrado para uma extensão. Para alterar o padrão, use a tela oficial do Windows e pesquise a extensão indicada. A escolha e sua confirmação são feitas lá. Depois, atualize a consulta aqui."),fileLayout,files);auto *form=new QFormLayout;fileLayout->addLayout(form);m_extension=new QLineEdit(extension.isEmpty()?".txt":extension,files);m_extension->setObjectName("associationExtension");m_extension->setMaxLength(255);form->addRow(tr("Extensão:"),m_extension);m_association=plain({},fileLayout,files,"associationResult");auto *actions=new QHBoxLayout;fileLayout->addLayout(actions);auto *query=new QPushButton(tr("Consultar / atualizar"),files);query->setObjectName("queryFileAssociation");auto *copy=new QPushButton(tr("Copiar extensão"),files);auto *settings=new QPushButton(tr("Alterar no Windows…"),files);settings->setObjectName("openDefaultApps");actions->addWidget(query);actions->addWidget(copy);actions->addWidget(settings);actions->addStretch();connect(query,&QPushButton::clicked,this,&WindowsIntegrationDialog::refreshAssociation);connect(m_extension,&QLineEdit::returnPressed,this,&WindowsIntegrationDialog::refreshAssociation);connect(copy,&QPushButton::clicked,this,[this]{const auto error=validateAssociationExtension(m_extension->text());if(!error.isEmpty()){m_association->setText(error);return;}qApp->clipboard()->setText(m_extension->text());});connect(settings,&QPushButton::clicked,this,[this]{if(QDesktopServices::openUrl(defaultAppsSettingsUrl()))m_association->setText(tr("Configurações de aplicativos padrão abertas. Pesquise %1 e escolha o programa; depois atualize a consulta.").arg(m_extension->text()));else m_association->setText(tr("O Windows não confirmou a abertura das Configurações."));});fileLayout->addStretch();
    auto *folders=new QWidget(tabs);auto *folderLayout=new QVBoxLayout(folders);tabs->addTab(folders,tr("Pastas físicas"));plain(tr("Opção para encaminhar a ação Abrir de pastas físicas do Shell a esta cópia do Directory Open. Escopo: comandos de diretórios; Win+E, pastas virtuais e diálogos de seleção permanecem sob controle do Windows. O executável deve continuar no local abaixo enquanto a opção estiver ativada."),folderLayout,folders);plain(tr("Executável: %1").arg(QDir::toNativeSeparators(m_executable)),folderLayout,folders);if(m_registry.isolated)plain(tr("Demonstração: registro isolado, sem alterar a abertura real de pastas."),folderLayout,folders);m_current=plain({},folderLayout,folders,"folderIntegrationCurrent");m_previous=plain({},folderLayout,folders,"folderIntegrationPrevious");plain(tr("A ativação grava primeiro um backup e um registro de recuperação, somente no seu usuário. As etapas podem produzir estado parcial em caso de interrupção; use Atualizar e reverta a tentativa após revisar. Restaurar recupera valores e ausências anteriores; chaves de estrutura são preservadas. Mudanças feitas por outro programa impedem a restauração automática."),folderLayout,folders);auto *folderActions=new QHBoxLayout;folderLayout->addLayout(folderActions);m_enable=new QPushButton(tr("Ativar para esta cópia…"),folders);m_enable->setObjectName("enableFolderIntegration");m_restore=new QPushButton(tr("Restaurar configuração anterior…"),folders);m_restore->setObjectName("restoreFolderIntegration");auto *reload=new QPushButton(tr("Atualizar estado"),folders);reload->setObjectName("refreshFolderIntegration");folderActions->addWidget(m_enable);folderActions->addWidget(m_restore);folderActions->addWidget(reload);folderActions->addStretch();connect(reload,&QPushButton::clicked,this,&WindowsIntegrationDialog::refreshFolders);connect(m_enable,&QPushButton::clicked,this,[this]{change(true);});connect(m_restore,&QPushButton::clicked,this,[this]{change(false);});folderLayout->addStretch();
    m_status=plain(tr("Nenhuma configuração alterada ao abrir esta tela."),layout,this,"windowsIntegrationStatus");auto *bottom=new QHBoxLayout;layout->addLayout(bottom);bottom->addStretch();auto *close=new QPushButton(tr("Fechar"),this);close->setObjectName("closeWindowsIntegration");bottom->addWidget(close);connect(close,&QPushButton::clicked,this,&QDialog::reject);refreshAssociation();refreshFolders();
}
void WindowsIntegrationDialog::refreshAssociation(){const auto result=queryFileAssociation(m_extension->text());if(result.state==AssociationState::Missing)m_association->setText(tr("O Windows não informou uma associação para esta extensão."));else if(result.state==AssociationState::Failed)m_association->setText(result.error);else m_association->setText(tr("Aplicativo: %1\nExecutável: %2\nIdentificação: %3%4").arg(result.application.isEmpty()?tr("não informado"):result.application,result.executable.isEmpty()?tr("não informado"):result.executable,result.programId.isEmpty()?tr("não informada"):result.programId,result.error.isEmpty()?QString{}:"\n"+result.error));}
void WindowsIntegrationDialog::refreshFolders(){m_snapshot=inspectFolderIntegration(m_registry);if(!m_snapshot.error.isEmpty()){m_current->setText(m_snapshot.error);m_previous->clear();m_enable->setEnabled(false);m_restore->setEnabled(false);return;}m_current->setText((m_snapshot.pending?(m_snapshot.aligned?tr("Alteração incompleta; é possível reverter a tentativa.\n"):tr("Alteração incompleta modificada externamente; revisão manual necessária.\n")):m_snapshot.enabled?(m_snapshot.aligned?tr("Integração ativa e conferida.\n"):tr("O registro ativo foi modificado externamente.\n")):tr("Integração desativada.\n"))+m_snapshot.current);m_previous->setText(m_snapshot.previous.isEmpty()?tr("Nenhum backup desta integração registrado."):(m_snapshot.pending?tr("Estado anterior à tentativa:\n"):tr("Backup anterior:\n"))+m_snapshot.previous);m_enable->setEnabled(!m_snapshot.pending&&(!m_snapshot.enabled||m_snapshot.aligned)&&!(m_snapshot.aligned&&m_snapshot.executable==m_executable));m_restore->setText(m_snapshot.pending?tr("Reverter alteração incompleta…"):tr("Restaurar configuração anterior…"));m_restore->setEnabled((m_snapshot.pending||m_snapshot.enabled)&&m_snapshot.aligned);}
void WindowsIntegrationDialog::change(bool enable){
    const auto reviewed=m_snapshot;if(!reviewed.error.isEmpty())return;QMessageBox question(QMessageBox::Question,enable?tr("Ativar abertura de pastas"):tr("Restaurar abertura de pastas"),enable?tr("Encaminhar a ação Abrir de pastas físicas para:\n%1\n\nO backup e o comando serão gravados no registro do seu usuário. Esta opção altera a abertura de diretórios pelo Shell. Confira o escopo antes de ativar.").arg(QDir::toNativeSeparators(m_executable)):reviewed.pending?tr("Reverter a tentativa incompleta ao estado anterior à tentativa? Uma integração já ativa antes dela pode voltar a ficar ativa. Revise o resultado antes de outra alteração."):tr("Restaurar os valores anteriores da abertura de pastas? A alteração será recusada se outro programa tiver modificado a configuração conferida."),QMessageBox::Yes|QMessageBox::No,this);question.setTextFormat(Qt::PlainText);question.setObjectName("confirmWindowsIntegration");question.setDefaultButton(QMessageBox::No);question.setDetailedText(reviewed.current+"\n\n"+reviewed.previous);if(question.exec()!=QMessageBox::Yes)return;const auto result=enable?enableFolderIntegration(m_registry,m_executable,reviewed.revision):restoreFolderIntegration(m_registry,reviewed.revision);m_status->setText(result.message);refreshFolders();
}
